INSERT INTO kairo.questions (id, subject, topic, subtopic, learning_objective, concepts_tested, prerequisite_concepts, difficulty_rating, cognitive_level, estimated_solving_time_sec, reading_load, calculation_load, distractors, skills_assessed, source, year, exam_body, related_question_ids, stem, options, correct_option, explanation, lifecycle_state, empirical_stats) VALUES
('mathematics_0098', 'Mathematics', 'Simultaneous equations', 'Simultaneous Equations (Linear and Quadratic)', NULL, '[{"weight": 1, "conceptId": "simlnq"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "(2,3) and (3,5) do not satisfy m+n=7 for both pairs, an invalid solution set.", "misconceptionId": "guessed_no_reasoning"}, {"option": "C", "explanation": "(5,2) and (5,3) repeats a value inconsistently and (5,3) does not satisfy m^2+n^2=29.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "(5,3) and (3,5) satisfy m+n=8, not 7, an arithmetic slip in checking the sum.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Solve the equations m 2 + n 2 = 29 m + n = 7', '[{"label": "A", "text": "(2, 3) and ( 3, 5)", "isCorrect": false}, {"label": "B", "text": "(2, 5) and (5, 2)", "isCorrect": true}, {"label": "C", "text": "(5, 2) and ( 5, 3)", "isCorrect": false}, {"label": "D", "text": "(5, 3) and (3, 5)", "isCorrect": false}]'::jsonb, 'B', 'From m+n=7, (m+n)^2=49=m^2+2mn+n^2, so 2mn=49-29=20, giving mn=10. Then m and n are roots of t^2-7t+10=0, i.e. (t-5)(t-2)=0, so (m,n)=(2,5) or (5,2).', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0099', 'Mathematics', 'Integration', 'Integration by Substitution (Power Rule)', NULL, '[{"weight": 1, "conceptId": "intsub"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "B", "explanation": "6/5(2x-3)^(5/3)+k forgets to divide by 2 for du=2dx, doubling the correct coefficient.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "(2x-3)^(5/3)+k drops the 3/5 coefficient from the power rule entirely.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "2(2x-3)^(5/3)+k mistakenly keeps the original coefficient of 2 without applying the power rule''s 3/5 factor.", "misconceptionId": "formula_recall_error"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Evaluate the integral of 2(2x - 3)^(2/3) dx', '[{"label": "A", "text": "3/5(2x-3)^(5/3) + k", "isCorrect": true}, {"label": "B", "text": "6/5(2x-3)^(5/3) + k", "isCorrect": false}, {"label": "C", "text": "(2x-3)^(5/3) + k", "isCorrect": false}, {"label": "D", "text": "2(2x-3)^(5/3) + k", "isCorrect": false}]'::jsonb, 'A', 'Let u=2x-3, du=2dx. Then the integral becomes the integral of u^(2/3) du = (3/5)u^(5/3) + k = (3/5)(2x-3)^(5/3) + k.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0100', 'Mathematics', 'Circles', 'Arc Length from Chord Equal to Radius', NULL, '[{"weight": 1, "conceptId": "arcchr"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "pi r/6 halves the correct central angle, from mistakenly using 30 degrees instead of 60.", "misconceptionId": "arithmetic_slip"}, {"option": "B", "explanation": "pi r/2 uses a central angle of 90 degrees instead of the correct 60 degrees.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "pi r/12 results from an arithmetic slip while converting the central angle to radians.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'The chord ST of a circle is equal to the radius, r, of the circle. Find the length of arc ST.', '[{"label": "A", "text": "πr/6", "isCorrect": false}, {"label": "B", "text": "πr/2", "isCorrect": false}, {"label": "C", "text": "πr/12", "isCorrect": false}, {"label": "D", "text": "πr/3", "isCorrect": true}]'::jsonb, 'D', 'If chord ST equals the radius r, triangle OST (O the centre) is equilateral, so the central angle is 60 degrees = pi/3 radians. Arc length = r x theta = r x pi/3 = pi r/3.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0101', 'Mathematics', 'Arithmetic progression', 'Sum of an Arithmetic Progression', NULL, '[{"weight": 1, "conceptId": "mathap01"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "58 years results from mistakenly treating the total savings as directly proportional to years without using the AP sum formula.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "100 years results from an arithmetic slip while solving the quadratic in n.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "29 years results from a slip while factorizing or solving the quadratic n^2+9n-580=0.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'A man saves N 100.00 in his first year of work and each year saves N 20.00 more in the preceding year. In how many years will he save N 5800.00?', '[{"label": "A", "text": "58 years", "isCorrect": false}, {"label": "B", "text": "100 years.", "isCorrect": false}, {"label": "C", "text": "20 years", "isCorrect": true}, {"label": "D", "text": "29 years", "isCorrect": false}]'::jsonb, 'C', 'Using Sn=n/2(2a+(n-1)d) with a=100, d=20: 5800=n/2(200+20(n-1)), which simplifies to n^2+9n-580=0. Solving gives n=20 (the positive root).', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0102', 'Mathematics', 'Measures of central tendency', 'Mode', NULL, '[{"weight": 1, "conceptId": "mathmod1"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "49 is the square of 7 (the highest frequency value itself), mistaken for the mode.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "25 is the square of 5, not related to the correct mode of 11.", "misconceptionId": "guessed_no_reasoning"}, {"option": "D", "explanation": "64 is the square of 8, mistakenly identifying 8 as the mode instead of 11.", "misconceptionId": "misread_graph"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Given the scores: 4, 7, 8, 11, 13, 8 with corresponding frequencies: 3, 5, 2, 7, 2, 1 respectively. Find the square of the mode.', '[{"label": "A", "text": "49", "isCorrect": false}, {"label": "B", "text": "121", "isCorrect": true}, {"label": "C", "text": "25", "isCorrect": false}, {"label": "D", "text": "64", "isCorrect": false}]'::jsonb, 'B', 'The highest frequency (7) corresponds to the score 11, so the mode is 11. Its square is 11^2=121.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0103', 'Mathematics', 'Polygons', 'Interior and Exterior Angles', NULL, '[{"weight": 1, "conceptId": "i49kq7"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "B", "explanation": "2 results from a formula recall error, confusing the exterior angle value with the number of sides.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "3 results from an arithmetic slip while dividing 360 by the exterior angle.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "8 results from an arithmetic slip while computing the exterior angle before dividing into 360.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Find the number of sides of a regular polygon whose interior angle is twice the exterior angle.', '[{"label": "A", "text": "6", "isCorrect": true}, {"label": "B", "text": "2", "isCorrect": false}, {"label": "C", "text": "3", "isCorrect": false}, {"label": "D", "text": "8", "isCorrect": false}]'::jsonb, 'A', 'Interior + exterior = 180. If interior = 2 x exterior, then 3 x exterior = 180, so exterior = 60 degrees. Number of sides = 360/60 = 6.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0104', 'Mathematics', 'Arithmetic progression', 'nth Term of an Arithmetic Progression', NULL, '[{"weight": 1, "conceptId": "j8p7et"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "Zero would only be correct if d were also zero, which is not implied by the given condition.", "misconceptionId": "overgeneralized_rule"}, {"option": "B", "explanation": "Half of the common difference misreads the relationship a=d derived from the given condition.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "Double the common difference misreads the relationship a=d derived from the given condition.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'The sixth term of an A.P is half of its twelfth term. The first term of the A.P is equal to', '[{"label": "A", "text": "zero", "isCorrect": false}, {"label": "B", "text": "half of the common difference", "isCorrect": false}, {"label": "C", "text": "double the common difference", "isCorrect": false}, {"label": "D", "text": "the common difference", "isCorrect": true}]'::jsonb, 'D', 'The 6th term is a+5d and the 12th term is a+11d. Given a+5d=(1/2)(a+11d), solving gives 2a+10d=a+11d, so a=d, i.e. the first term equals the common difference.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0105', 'Mathematics', 'Measures of dispersion', 'Variance', NULL, '[{"weight": 1, "conceptId": "varnc1"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "6 is the maximum value in the data set, not the variance.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "sqrt(6) is not a value that arises from this variance calculation; it conflates the data with the standard deviation formula.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "sqrt(5) is the standard deviation, not the variance itself -- a units confusion.", "misconceptionId": "misunderstood_terminology"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Find the variance of 2, 6, 8, 6, 2 and 6', '[{"label": "A", "text": "6", "isCorrect": false}, {"label": "B", "text": "5", "isCorrect": true}, {"label": "C", "text": "√6", "isCorrect": false}, {"label": "D", "text": "√5", "isCorrect": false}]'::jsonb, 'B', 'Mean = (2+6+8+6+2+6)/6 = 30/6 = 5. Squared deviations: 9,1,9,1,9,1, summing to 30. Variance = 30/6 = 5.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0106', 'Mathematics', 'Mensuration', 'Cone Formed from a Sector (Base Radius)', NULL, '[{"weight": 1, "conceptId": "conesc"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "8cm results from an arithmetic slip while equating the arc length to the base circumference.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "9cm results from a slip in simplifying the fraction 300/360 before computing the arc length.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "7cm results from an arithmetic slip in the final division step.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'A sector of a circle of radius 7.2cm which subtends an angle of 300° at the centre is used to form a cone. What is the radius of the base of the cone?', '[{"label": "A", "text": "8cm", "isCorrect": false}, {"label": "B", "text": "6cm", "isCorrect": true}, {"label": "C", "text": "9cm", "isCorrect": false}, {"label": "D", "text": "7cm", "isCorrect": false}]'::jsonb, 'B', 'The arc length of the sector becomes the base circumference of the cone: (300/360) x 2pi(7.2) = 12pi. Setting this equal to 2pi(r) gives r=6cm.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0107', 'Mathematics', 'Measures of central tendency', 'Mean', NULL, '[{"weight": 1, "conceptId": "p7l3z1"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "7.0 results from an arithmetic slip while summing the score x frequency products.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "9.5 results from an arithmetic slip while dividing the total by the sum of frequencies.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "11.0 mistakes the highest-frequency score for the mean.", "misconceptionId": "confused_similar_concepts"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Given the scores: 4, 7, 8, 11, 13, 8 with corresponding frequencies: 3, 5, 2, 7, 2, 1 respectively. The mean score is', '[{"label": "A", "text": "7.0", "isCorrect": false}, {"label": "B", "text": "8.7", "isCorrect": true}, {"label": "C", "text": "9.5", "isCorrect": false}, {"label": "D", "text": "11.0", "isCorrect": false}]'::jsonb, 'B', 'Mean = sum(score x frequency)/sum(frequency) = (4x3+7x5+8x2+11x7+13x2+8x1)/20 = 174/20 = 8.7.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0108', 'Mathematics', 'Algebraic expressions', 'Evaluating Algebraic Fraction Expressions with a Substitution', NULL, '[{"weight": 1, "conceptId": "algfrs"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "5/8 is only the numerator of the final division, before dividing by 1/4.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "5/32 results from multiplying instead of dividing by the reciprocal of 1/4.", "misconceptionId": "sign_error"}, {"option": "D", "explanation": "5/16 results from an arithmetic slip while combining the fractions.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'If x = y/2, evaluate (x^3/y^3 + 1/2) divided by (1/2 - x^2/y^2)', '[{"label": "A", "text": "5/8", "isCorrect": false}, {"label": "B", "text": "5/2", "isCorrect": true}, {"label": "C", "text": "5/32", "isCorrect": false}, {"label": "D", "text": "5/16", "isCorrect": false}]'::jsonb, 'B', 'With x/y=1/2: x^3/y^3=1/8, so x^3/y^3+1/2=5/8. Also x^2/y^2=1/4, so 1/2-x^2/y^2=1/4. Dividing: (5/8)/(1/4)=5/2.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0109', 'Mathematics', 'Quadratic equations', 'Finding a Parameter from Two Intersecting Quadratics', NULL, '[{"weight": 1, "conceptId": "paraqd"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "(q-8)/7 results from an algebraic slip while isolating p, mixing up the coefficients.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "(8-q)/2 results from an arithmetic slip while dividing through by 4.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "(7+q)/8 has a sign error on q and an incorrect denominator from a formula recall slip.", "misconceptionId": "sign_error"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'If two graphs y = px^2 + q and y = 2x^2 - 1 intersect at x = 2, find the value of p in terms of q.', '[{"label": "A", "text": "(q-8)/7", "isCorrect": false}, {"label": "B", "text": "(7-q)/4", "isCorrect": true}, {"label": "C", "text": "(8-q)/2", "isCorrect": false}, {"label": "D", "text": "(7+q)/8", "isCorrect": false}]'::jsonb, 'B', 'At the intersection x=2, both equations give the same y: p(2)^2+q = 2(2)^2-1, i.e. 4p+q=7, so p=(7-q)/4.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0110', 'Mathematics', 'Permutations and combinations', 'Permutations (nPr Notation)', NULL, '[{"weight": 1, "conceptId": "npermn"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "B", "explanation": "33 does not correspond to any valid nPr value for n=6.", "misconceptionId": "guessed_no_reasoning"}, {"option": "C", "explanation": "35 does not correspond to any valid nPr value for n=6.", "misconceptionId": "guessed_no_reasoning"}, {"option": "D", "explanation": "15 is 6C2 (a combination), not 6P2 (a permutation) -- confusing the two formulas.", "misconceptionId": "confused_similar_concepts"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'If 6Pr = 6, find the value of 6P(r+1)', '[{"label": "A", "text": "30", "isCorrect": true}, {"label": "B", "text": "33", "isCorrect": false}, {"label": "C", "text": "35", "isCorrect": false}, {"label": "D", "text": "15", "isCorrect": false}]'::jsonb, 'A', '6Pr=6 is satisfied by r=1, since 6P1=6. Then 6P(r+1)=6P2=6x5=30.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0111', 'Mathematics', 'Measures of dispersion', 'Range and Mode', NULL, '[{"weight": 1, "conceptId": "1eyy37"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "3/4 results from an arithmetic slip while subtracting the fractions.", "misconceptionId": "arithmetic_slip"}, {"option": "B", "explanation": "5/6 results from using the wrong pair of extreme values.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "7/6 results from an arithmetic slip in finding a common denominator.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Find the range of 1/6, 1/3, 3/2, 2/3, 8/9, and 4/3', '[{"label": "A", "text": "3/4", "isCorrect": false}, {"label": "B", "text": "5/6", "isCorrect": false}, {"label": "C", "text": "7/6", "isCorrect": false}, {"label": "D", "text": "4/3", "isCorrect": true}]'::jsonb, 'D', 'The largest value is 3/2 and the smallest is 1/6. Range = 3/2-1/6 = 9/6-1/6 = 8/6 = 4/3.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0112', 'Mathematics', 'Mensuration', 'Volume of Solids', NULL, '[{"weight": 1, "conceptId": "mathmen2"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "23m results from an arithmetic slip while dividing the volume by 154.", "misconceptionId": "arithmetic_slip"}, {"option": "B", "explanation": "25m results from an arithmetic slip while dividing the volume by 154.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "22m mistakes the value of pi (22/7) itself for the depth.", "misconceptionId": "confused_similar_concepts"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'A cylindrical tank has a capacity of 3080 m3. What is the depth of the tank if the diameter of its base is 14 m? (Take pi = 22/7)', '[{"label": "A", "text": "23 m", "isCorrect": false}, {"label": "B", "text": "25 m", "isCorrect": false}, {"label": "C", "text": "20 m", "isCorrect": true}, {"label": "D", "text": "22 m", "isCorrect": false}]'::jsonb, 'C', 'V=pi r^2 h, with r=7m: 3080 = (22/7)(49)h = 154h, so h=3080/154=20m.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0113', 'Mathematics', 'Differentiation', 'Coefficients from Derivative Conditions', NULL, '[{"weight": 1, "conceptId": "aq6l6g"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "4 results from an arithmetic slip while solving 4k+1=9 for k.", "misconceptionId": "arithmetic_slip"}, {"option": "B", "explanation": "3 results from an arithmetic slip while isolating k.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "1 results from mistakenly treating 4k+1=9 as k+1=9-4k or a similar mis-rearrangement.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'If the gradient of the curve y = 2kx^2 + x + 1 at x = 1 is 9, find k.', '[{"label": "A", "text": "4", "isCorrect": false}, {"label": "B", "text": "3", "isCorrect": false}, {"label": "C", "text": "2", "isCorrect": true}, {"label": "D", "text": "1", "isCorrect": false}]'::jsonb, 'C', 'dy/dx=4kx+1. At x=1, this equals 9: 4k+1=9, so 4k=8 and k=2.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0114', 'Mathematics', 'Fractions, decimals and approximations', 'Evaluating Decimal Expressions to Given Decimal Places', NULL, '[{"weight": 1, "conceptId": "decexp"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "20.980 results from a sign error, adding instead of subtracting the product.", "misconceptionId": "sign_error"}, {"option": "B", "explanation": "20.351 truncates the exact value 20.351538 instead of rounding it up to 3 decimal places.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "20.981 combines a sign error (adding instead of subtracting) with a rounding slip.", "misconceptionId": "sign_error"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Evaluate 21.05347 - 1.6324 x 0.43 to 3 decimal places', '[{"label": "A", "text": "20.980", "isCorrect": false}, {"label": "B", "text": "20.351", "isCorrect": false}, {"label": "C", "text": "20.981", "isCorrect": false}, {"label": "D", "text": "20.352", "isCorrect": true}]'::jsonb, 'D', '1.6324 x 0.43 = 0.701932. Then 21.05347 - 0.701932 = 20.351538, which rounds to 20.352 to 3 decimal places.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0115', 'Mathematics', 'Matrices and determinants', 'Determinant of a 3x3 Matrix', NULL, '[{"weight": 1, "conceptId": "f07uqn"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "B", "explanation": "-12 results from an arithmetic slip while expanding one of the 2x2 minors.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "4 has the correct magnitude but the wrong sign, from a sign error in the cofactor expansion.", "misconceptionId": "sign_error"}, {"option": "D", "explanation": "-2 results from an arithmetic slip while combining the three cofactor terms.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Evaluate the determinant of [[-1,-1,-1],[3,1,-1],[1,2,1]]', '[{"label": "A", "text": "-4", "isCorrect": true}, {"label": "B", "text": "-12", "isCorrect": false}, {"label": "C", "text": "4", "isCorrect": false}, {"label": "D", "text": "-2", "isCorrect": false}]'::jsonb, 'A', 'Expanding along the first row: -1(1x1-(-1)x2) - (-1)(3x1-(-1)x1) + (-1)(3x2-1x1) = -1(3) + 1(4) - 1(5) = -3+4-5 = -4.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0116', 'Mathematics', 'Applications of differentiation', 'Related Rates', NULL, '[{"weight": 1, "conceptId": "87au5b"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "12pi results from an arithmetic slip while differentiating, e.g. dropping a factor of r^2 correctly but mis-multiplying the constant.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "24pi results from a formula recall error, perhaps confusing the volume derivative with a surface-area-related quantity.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "8pi results from a factor-of-2 arithmetic slip while simplifying 4pi r^2 at r=1.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Find the rate of change of the volume, V of a sphere with respect to its radius, r when r = 1.', '[{"label": "A", "text": "12π", "isCorrect": false}, {"label": "B", "text": "4π", "isCorrect": true}, {"label": "C", "text": "24π", "isCorrect": false}, {"label": "D", "text": "8π", "isCorrect": false}]'::jsonb, 'B', 'V=(4/3)pi r^3, so dV/dr=4pi r^2. At r=1, dV/dr=4pi.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0117', 'Mathematics', 'Matrices and determinants', 'Scalar Multiplication of a Matrix', NULL, '[{"weight": 1, "conceptId": "sclmtx"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "This has a sign error in the first row, keeping -4 positive instead of correctly computing -2x-2=4.", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "This leaves the second and third rows unmultiplied, only scaling the first row by -2.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "This has sign/arithmetic slips scattered in the second and third rows of the scalar multiplication.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'If P = [[3,-2,4],[5,0,6],[7,5,-1]], then -2P is', '[{"label": "A", "text": "[[-6,-4,2],[-10,-2,-12],[-14,-10,-2]]", "isCorrect": false}, {"label": "B", "text": "[[-6,4,-8],[-10,0,-12],[-14,-10,2]]", "isCorrect": true}, {"label": "C", "text": "[[-6,4,-8],[5,0,6],[7,5,-1]]", "isCorrect": false}, {"label": "D", "text": "[[-6,4,-8],[-10,0,6],[-14,5,-1]]", "isCorrect": false}]'::jsonb, 'B', 'Multiplying every entry of P by -2 gives -2P = [[-6,4,-8],[-10,0,-12],[-14,-10,2]].', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0118', 'Mathematics', 'Probability', 'Independent Events', NULL, '[{"weight": 1, "conceptId": "vhs1k3"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "1/4 results from wrongly multiplying two independent 1/2 probabilities, which is not justified by the information given.", "misconceptionId": "guessed_no_reasoning"}, {"option": "B", "explanation": "1/2 mistakenly treats a draw as equally likely against a single combined ''not draw'' outcome, ignoring that win and lose are two separate outcomes.", "misconceptionId": "overgeneralized_rule"}, {"option": "D", "explanation": "2/3 mistakenly assigns the combined probability of the two non-draw outcomes to the draw itself.", "misconceptionId": "confused_similar_concepts"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Teams P and Q are involved in a game of football. What is the probability that the game ends in a draw?', '[{"label": "A", "text": "2/3", "isCorrect": false}, {"label": "B", "text": "1/2", "isCorrect": false}, {"label": "C", "text": "1/3", "isCorrect": true}, {"label": "D", "text": "1/4", "isCorrect": false}]'::jsonb, 'C', 'A football match has three possible outcomes for team P: win, lose, or draw. With no other information given, these are treated as equally likely, so the probability of a draw is 1/3.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0119', 'Mathematics', 'Inequalities', 'Linear Inequalities (Integer Solutions)', NULL, '[{"weight": 1, "conceptId": "linint"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "B", "explanation": "(1,3) is invalid since y<3 is a strict inequality, and (2,2) fails 3(2)+5(2)=16>15.", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "(1,3) is invalid since y<3 excludes y=3, and this set omits the valid pair (2,1).", "misconceptionId": "sign_error"}, {"option": "D", "explanation": "(1,3) is invalid since y<3 excludes y=3, an off-by-one error at the boundary.", "misconceptionId": "sign_error"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Find the integral values of x and y satisfying the inequality 3y + 5x <= 15, given that y > 0, y < 3, and x > 0.', '[{"label": "A", "text": "( 1, 1), (1, 2), (2, 1)", "isCorrect": true}, {"label": "B", "text": "( 1, 1), (1, 3), (2, 2)", "isCorrect": false}, {"label": "C", "text": "( 1, 1), (1, 2) (1, 3)", "isCorrect": false}, {"label": "D", "text": "( 1, 1), (1, 3), (2, 1)", "isCorrect": false}]'::jsonb, 'A', 'Since 0<y<3, the only integer value is y=1 or y=2. For y=1: 3+5x<=15 gives x<=2.4, so x=1,2. For y=2: 6+5x<=15 gives x<=1.8, so x=1. The integral solutions are (1,1),(1,2),(2,1).', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb);
